//! Rust bindings to `libpcp_mmv`, the [Performance Co-Pilot] library for
//! instrumenting applications with Memory Mapped Value (MMV) metrics.
//!
//! **This crate is a 2017 proof of concept.** For production use, see
//! [hornet](https://github.com/performancecopilot/hornet), a pure-Rust
//! implementation of the PCP instrumentation API.
//!
//! The raw bindings generated by `bindgen` live in [`sys`]. The rest of the
//! crate is a small safe wrapper around the original `mmv_stats_init` API:
//!
//! ```no_run
//! use pcp_mmv::{Flags, MetricSem, MetricType, Metric, Mmv, Units, PM_COUNT_ONE};
//!
//! let requests = Metric::new(
//!     "requests", 1, MetricType::U64, MetricSem::Counter,
//!     Units::new(0, 0, 1, 0, 0, PM_COUNT_ONE), 0,
//!     "Requests served", "Number of requests served since startup",
//! );
//! let mmv = Mmv::start("myapp", 1, Flags::empty(), &[requests], &[])?;
//! let value = mmv.lookup_value("requests", None).expect("metric exists");
//! value.inc(1.0);
//! # Ok::<(), std::io::Error>(())
//! ```
//!
//! [Performance Co-Pilot]: https://pcp.io

#![warn(missing_docs)]

#[cfg(not(all(target_endian = "little", target_pointer_width = "64")))]
compile_error!(
    "src/sys.rs was generated for 64-bit little-endian targets; \
     regenerate it with ./generate-bindings.sh"
);

/// Raw bindings to `<pcp/mmv_stats.h>`, generated by `bindgen`.
// `unknown_lints`: bindgen allows lints that are newer than the MSRV.
#[allow(
    missing_docs,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    unknown_lints,
    clippy::all
)]
#[rustfmt::skip]
pub mod sys;

pub use sys::{
    PM_COUNT_ONE, PM_SPACE_BYTE, PM_SPACE_EBYTE, PM_SPACE_GBYTE, PM_SPACE_KBYTE, PM_SPACE_MBYTE,
    PM_SPACE_PBYTE, PM_SPACE_TBYTE, PM_TIME_HOUR, PM_TIME_MIN, PM_TIME_MSEC, PM_TIME_NSEC,
    PM_TIME_SEC, PM_TIME_USEC,
};

use core::ffi::{c_char, c_int, c_void};
use std::ffi::CString;
use std::io;
use std::ptr::{self, NonNull};

/// Maximum length of a metric name or instance name, including the
/// terminating NUL byte.
const NAME_MAX: usize = sys::MMV_NAMEMAX as usize;

/// Converts `s` to a `CString`, panicking with a helpful message if it
/// contains a NUL byte.
fn cstring(what: &str, s: &str) -> CString {
    CString::new(s).unwrap_or_else(|_| panic!("{what} {s:?} contains a NUL byte"))
}

/// Converts `s` to the fixed-size, NUL-terminated name array used by
/// `mmv_metric_t` and `mmv_instances_t`.
fn name_array(what: &str, s: &str) -> [c_char; NAME_MAX] {
    let s = cstring(what, s);
    let bytes = s.as_bytes_with_nul();
    assert!(
        bytes.len() <= NAME_MAX,
        "{what} {s:?} is longer than {} bytes",
        NAME_MAX - 1
    );
    let mut array = [0; NAME_MAX];
    for (dst, &src) in array.iter_mut().zip(bytes) {
        *dst = src as c_char;
    }
    array
}

/// Converts a slice length to the `int` count expected by `libpcp_mmv`.
fn count(what: &str, len: usize) -> io::Result<c_int> {
    c_int::try_from(len)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, format!("too many {what}")))
}

/// The data type of a metric's value.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum MetricType {
    /// 32-bit signed integer.
    I32,
    /// 32-bit unsigned integer.
    U32,
    /// 64-bit signed integer.
    I64,
    /// 64-bit unsigned integer.
    U64,
    /// 32-bit floating point.
    Float,
    /// 64-bit floating point.
    Double,
    /// String of up to 255 bytes; see [`AtomValue::set_string`].
    String,
    /// 64-bit elapsed time; see [`AtomValue::inc`].
    Elapsed,
}

impl MetricType {
    fn raw(self) -> sys::mmv_metric_type_t {
        match self {
            MetricType::I32 => sys::MMV_TYPE_I32,
            MetricType::U32 => sys::MMV_TYPE_U32,
            MetricType::I64 => sys::MMV_TYPE_I64,
            MetricType::U64 => sys::MMV_TYPE_U64,
            MetricType::Float => sys::MMV_TYPE_FLOAT,
            MetricType::Double => sys::MMV_TYPE_DOUBLE,
            MetricType::String => sys::MMV_TYPE_STRING,
            MetricType::Elapsed => sys::MMV_TYPE_ELAPSED,
        }
    }
}

/// The semantics of a metric's value.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum MetricSem {
    /// A monotonically increasing counter.
    Counter,
    /// An instantaneous value that can go up or down.
    Instant,
    /// A value that changes rarely, if ever.
    Discrete,
}

impl MetricSem {
    fn raw(self) -> sys::mmv_metric_sem_t {
        match self {
            MetricSem::Counter => sys::MMV_SEM_COUNTER,
            MetricSem::Instant => sys::MMV_SEM_INSTANT,
            MetricSem::Discrete => sys::MMV_SEM_DISCRETE,
        }
    }
}

/// The dimension and scale of a metric (PCP's `pmUnits`).
pub type Units = sys::pmUnits;

impl Units {
    /// Creates units from dimensions and scales, like PCP's `MMV_UNITS`
    /// macro.
    ///
    /// Scales are one of the `PM_SPACE_*`, `PM_TIME_*` and `PM_COUNT_*`
    /// constants. For example, microseconds are
    /// `Units::new(0, 1, 0, 0, PM_TIME_USEC, 0)` and a plain count is
    /// `Units::new(0, 0, 1, 0, 0, PM_COUNT_ONE)`. Dimensionless metrics use
    /// `Units::default()`.
    pub fn new(
        dim_space: i32,
        dim_time: i32,
        dim_count: i32,
        scale_space: i32,
        scale_time: i32,
        scale_count: i32,
    ) -> Units {
        let mut units = Units::default();
        units.set_dimSpace(dim_space);
        units.set_dimTime(dim_time);
        units.set_dimCount(dim_count);
        units.set_scaleSpace(scale_space as u32);
        units.set_scaleTime(scale_time as u32);
        units.set_scaleCount(scale_count);
        units
    }
}

bitflags::bitflags! {
    /// Flags for an MMV file.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
    pub struct Flags: sys::mmv_stats_flags_t {
        /// Don't prefix metric names with the MMV file name.
        const NOPREFIX = sys::MMV_FLAG_NOPREFIX;
        /// Stop reporting metrics once the process has exited, and remove
        /// the file when the [`Mmv`] handle is dropped.
        const PROCESS = sys::MMV_FLAG_PROCESS;
        /// Treat sentinel values as "no value available".
        const SENTINEL = sys::MMV_FLAG_SENTINEL;
    }
}

/// One instance of an instance domain.
#[derive(Clone, Debug)]
pub struct Instance {
    internal: i32,
    external: [c_char; NAME_MAX],
}

impl Instance {
    /// Creates an instance with an internal ID and an external name.
    ///
    /// # Panics
    ///
    /// Panics if `external` contains a NUL byte or is longer than 63 bytes.
    pub fn new(internal: i32, external: &str) -> Instance {
        Instance {
            internal,
            external: name_array("instance name", external),
        }
    }
}

/// An instance domain: a set of instances that metrics can have values for.
#[derive(Clone, Debug)]
pub struct Indom {
    serial: u32,
    instances: Vec<Instance>,
    shorttext: CString,
    helptext: CString,
}

impl Indom {
    /// Creates an instance domain with a non-zero serial number.
    ///
    /// Help texts must be shorter than 256 bytes, or [`Mmv::start`] fails.
    ///
    /// # Panics
    ///
    /// Panics if `shorttext` or `helptext` contains a NUL byte.
    pub fn new(serial: u32, instances: &[Instance], shorttext: &str, helptext: &str) -> Indom {
        Indom {
            serial,
            instances: instances.to_vec(),
            shorttext: cstring("indom short text", shorttext),
            helptext: cstring("indom help text", helptext),
        }
    }
}

/// The description of a metric.
#[derive(Clone, Debug)]
pub struct Metric {
    name: [c_char; NAME_MAX],
    item: u32,
    type_: MetricType,
    semantics: MetricSem,
    dimension: Units,
    indom: u32,
    shorttext: CString,
    helptext: CString,
}

impl Metric {
    /// Creates a metric description.
    ///
    /// `item` must be unique within the MMV file. `indom` is the serial
    /// number of the metric's [`Indom`], or 0 for a metric with a single
    /// value. `libpcp_mmv` truncates help texts to 255 bytes.
    ///
    /// # Panics
    ///
    /// Panics if any string contains a NUL byte, or if `name` is longer than
    /// 63 bytes.
    #[allow(clippy::too_many_arguments)] // mirrors the fields of `mmv_metric_t`
    pub fn new(
        name: &str,
        item: u32,
        type_: MetricType,
        semantics: MetricSem,
        dimension: Units,
        indom: u32,
        shorttext: &str,
        helptext: &str,
    ) -> Metric {
        Metric {
            name: name_array("metric name", name),
            item,
            type_,
            semantics,
            dimension,
            indom,
            shorttext: cstring("metric short text", shorttext),
            helptext: cstring("metric help text", helptext),
        }
    }
}

/// A memory mapped MMV file, created by `mmv_stats_init`.
///
/// The file is unmapped when this handle is dropped. It is also removed if
/// [`Flags::PROCESS`] is set.
///
/// `Mmv` is `Send` but not `Sync`: `libpcp_mmv` updates values without
/// atomic operations, so all updates must happen on one thread at a time.
#[derive(Debug)]
pub struct Mmv {
    handle: NonNull<c_void>,
    name: CString,
}

// SAFETY: the handle is the address of a shared memory mapping with no
// thread affinity; `!Sync` keeps updates on one thread at a time.
unsafe impl Send for Mmv {}

impl Mmv {
    /// Creates and maps an MMV file containing `metrics` and `indoms`.
    ///
    /// A relative `name` creates the file `$PCP_TMP_DIR/mmv/<name>`, where
    /// PCP's MMV agent picks it up. An absolute path is used as is.
    ///
    /// `cluster_id` must be less than 4096.
    ///
    /// # Errors
    ///
    /// Returns the error reported by `libpcp_mmv`, for example `E2BIG` for
    /// an indom help text that is too long, `ESRCH` for a metric whose indom
    /// is missing, or an I/O error creating the file.
    ///
    /// # Panics
    ///
    /// Panics if `name` contains a NUL byte.
    pub fn start(
        name: &str,
        cluster_id: u32,
        flags: Flags,
        metrics: &[Metric],
        indoms: &[Indom],
    ) -> io::Result<Mmv> {
        let name = cstring("MMV file name", name);
        let cluster_id = c_int::try_from(cluster_id)
            .ok()
            .filter(|&id| id < 1 << 12)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "cluster ID must be less than 4096",
                )
            })?;

        // libpcp_mmv copies everything into the file, so these only need to
        // live until mmv_stats_init returns.
        let mut instances: Vec<Vec<sys::mmv_instances_t>> = indoms
            .iter()
            .map(|indom| {
                indom
                    .instances
                    .iter()
                    .map(|instance| sys::mmv_instances_t {
                        internal: instance.internal,
                        external: instance.external,
                    })
                    .collect()
            })
            .collect();
        let raw_indoms = indoms
            .iter()
            .zip(&mut instances)
            .map(|(indom, instances)| {
                Ok(sys::mmv_indom_t {
                    serial: indom.serial,
                    count: count("instances", instances.len())? as u32,
                    instances: instances.as_mut_ptr(),
                    shorttext: indom.shorttext.as_ptr().cast_mut(),
                    helptext: indom.helptext.as_ptr().cast_mut(),
                })
            })
            .collect::<io::Result<Vec<_>>>()?;
        let raw_metrics: Vec<sys::mmv_metric_t> = metrics
            .iter()
            .map(|metric| sys::mmv_metric_t {
                name: metric.name,
                item: metric.item,
                type_: metric.type_.raw(),
                semantics: metric.semantics.raw(),
                dimension: metric.dimension,
                indom: metric.indom,
                shorttext: metric.shorttext.as_ptr().cast_mut(),
                helptext: metric.helptext.as_ptr().cast_mut(),
            })
            .collect();

        // SAFETY: every pointer refers to a live, NUL-terminated string or to
        // an array whose length is passed alongside it.
        let handle = unsafe {
            sys::mmv_stats_init(
                name.as_ptr(),
                cluster_id,
                flags.bits(),
                raw_metrics.as_ptr(),
                count("metrics", raw_metrics.len())?,
                raw_indoms.as_ptr(),
                count("indoms", raw_indoms.len())?,
            )
        };
        match NonNull::new(handle) {
            Some(handle) => Ok(Mmv { handle, name }),
            None => Err(io::Error::last_os_error()),
        }
    }

    /// Looks up the value of `metric` for `instance`.
    ///
    /// `instance` is the external name of an instance, or `None` for a metric
    /// with a single value. Returns `None` if there is no such value.
    ///
    /// # Panics
    ///
    /// Panics if `metric` or `instance` contains a NUL byte.
    pub fn lookup_value(&self, metric: &str, instance: Option<&str>) -> Option<AtomValue<'_>> {
        let metric = cstring("metric name", metric);
        let instance = instance.map(|instance| cstring("instance name", instance));
        // SAFETY: the handle is a live mapping and both strings are
        // NUL-terminated.
        let atom = unsafe {
            sys::mmv_lookup_value_desc(
                self.handle.as_ptr(),
                metric.as_ptr(),
                instance.as_ref().map_or(ptr::null(), |i| i.as_ptr()),
            )
        };
        NonNull::new(atom).map(|atom| AtomValue { mmv: self, atom })
    }
}

impl Drop for Mmv {
    fn drop(&mut self) {
        // SAFETY: the handle came from mmv_stats_init with this name, and no
        // AtomValue can outlive `self`.
        unsafe { sys::mmv_stats_stop(self.name.as_ptr(), self.handle.as_ptr()) }
    }
}

/// A metric value inside a mapped MMV file, returned by
/// [`Mmv::lookup_value`].
///
/// Values borrow the [`Mmv`] they came from, so they cannot outlive the
/// mapping.
#[derive(Clone, Copy, Debug)]
pub struct AtomValue<'a> {
    mmv: &'a Mmv,
    atom: NonNull<sys::pmAtomValue>,
}

impl AtomValue<'_> {
    fn handle(&self) -> *mut c_void {
        self.mmv.handle.as_ptr()
    }

    fn ull_ptr(&self) -> *mut u64 {
        // SAFETY: `atom` points to a live pmAtomValue inside the mapping.
        unsafe { ptr::addr_of_mut!((*self.atom.as_ptr()).ull).cast() }
    }

    /// Adds `amount` to the value, converting it to the metric's type.
    ///
    /// For [`MetricType::Elapsed`] metrics, a negative `amount` starts an
    /// interval at that (negated) time in microseconds and a positive one
    /// ends it.
    pub fn inc(&self, amount: f64) {
        // SAFETY: the handle and value are live, and `!Sync` rules out
        // concurrent updates.
        unsafe { sys::mmv_inc_value(self.handle(), self.atom.as_ptr(), amount) }
    }

    /// Sets the value, converting `value` to the metric's type.
    pub fn set(&self, value: f64) {
        // SAFETY: as for `inc`.
        unsafe { sys::mmv_set_value(self.handle(), self.atom.as_ptr(), value) }
    }

    /// Sets the value of a [`MetricType::String`] metric.
    ///
    /// Like `libpcp_mmv`, this does nothing if the metric is not a string
    /// metric or if `value` is 255 bytes or longer.
    pub fn set_string(&self, value: &str) {
        let Ok(len) = c_int::try_from(value.len()) else {
            return;
        };
        // SAFETY: as for `inc`; `value` has `len` readable bytes.
        unsafe {
            sys::mmv_set_string(
                self.handle(),
                self.atom.as_ptr(),
                value.as_ptr().cast(),
                len,
            )
        }
    }

    /// Reads the value as a 64-bit unsigned integer.
    pub fn ull(&self) -> u64 {
        // SAFETY: the pointer is valid and aligned; volatile because other
        // processes read the mapping.
        unsafe { self.ull_ptr().read_volatile() }
    }

    /// Sets the value as a 64-bit unsigned integer, ignoring the metric's
    /// type.
    pub fn set_ull(&self, value: u64) {
        // SAFETY: as for `ull`.
        unsafe { self.ull_ptr().write_volatile(value) }
    }

    /// Adds to the value as a 64-bit unsigned integer, wrapping on
    /// overflow.
    pub fn inc_ull(&self, amount: u64) {
        self.set_ull(self.ull().wrapping_add(amount));
    }
}
